# Builds game/src/data.js from data/cards.json + data/corps.json (do not edit data.js by hand).
import json,os
D=os.path.dirname(os.path.abspath(__file__))
cards=json.load(open(os.path.join(D,'..','data','cards.json'),encoding='utf-8'))
corps=json.load(open(os.path.join(D,'..','data','corps.json'),encoding='utf-8'))
js='// Generated by game/gen-data.py from data/cards.json + data/corps.json. Do not edit by hand.\n(function(root){var D=root.OH_DATA={cards:%s,corps:%s};if(typeof module!=="undefined")module.exports=D;})(typeof window!=="undefined"?window:globalThis);\n'%(json.dumps(cards,separators=(',',':'),ensure_ascii=False),json.dumps(corps,separators=(',',':'),ensure_ascii=False))
open(os.path.join(D,'src','data.js'),'w',encoding='utf-8').write(js)
print('data.js: %d cards, %d corps'%(len(cards),len(corps)))
